let loadedRawData=null;document.addEventListener("DOMContentLoaded",(function(){const fileInput=document.getElementById("raw-file-input"),fileStatus=document.getElementById("file-status"),output=document.getElementById("output-area");function setLoadedData(data,sourceLabel){loadedRawData=data,fileStatus.textContent=`Loaded: ${sourceLabel} (${Array.isArray(data)?data.length:"?"} entries)`,fileStatus.classList.remove("error"),WF.generators&&WF.generators.length>0&&function(generator){if(!loadedRawData)return output.value="",void alert("Load a JSON file first, then run a generator.");output.value="";try{output.value=generator.run(loadedRawData)}catch(err){output.value=`Error: ${err.message}`}}(WF.generators[0])}fileInput.addEventListener("change",(function(event){const file=event.target.files[0];if(!file)return;const reader=new FileReader;reader.onload=function(e){try{setLoadedData(JSON.parse(e.target.result),file.name)}catch(err){message=`Invalid JSON in ${file.name}`,loadedRawData=null,fileStatus.textContent=message,fileStatus.classList.add("error")}var message},reader.readAsText(file)})),document.getElementById("btn-clear-output").addEventListener("click",(()=>{output.value=""})),document.getElementById("btn-copy-output").addEventListener("click",(async()=>{if(output.value){if(navigator.clipboard&&navigator.clipboard.writeText)try{return void await navigator.clipboard.writeText(output.value)}catch(err){}output.select();try{document.execCommand("copy")}catch(err){alert("Copy failed, please select and copy manually.")}output.setSelectionRange(0,0)}}))}));